         )

mapper.select:
SELECT * FROM item
WHERE seller_id = #{userId}
  AND is_deleted = 0
  AND (title LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC
    LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE item
SET status = #{status}, update_time = NOW()
WHERE id = #{id}

UPDATE item
SET is_deleted = 1, update_time = NOW()
WHERE id = #{id}
